//remove 4byte header
//split DTCs by 4 bytes
//check status byte - lower nibble must be odd = DTC is active
//ignode DTC as per list

string input = SharedMemory[param[0]].ToString();
string ignoreList = param[1];
string output = "";
string bit0true = "13579BDF";

for (int i = 8; i <= input.Length-8; i += 8)
        {
            string dtc = input.Substring(i, 8);
            string status = dtc.Substring(7,1);
            dtc = dtc.Substring(0,6);

            //test status bit and ignore list
            if (bit0true.Contains(status) && !ignoreList.Contains(dtc))
                {
                if (output.Length > 0) output += ",";
                output += dtc;
                }
        }

if (output.Length == 0) output = "All_OK";

return output;

//compose CarConfigGET -- to be ExpectedString
//param[0] - HEAT
//param[1] - 2way-4way Lumbar, Not CFGed
//param[2] - Ventilation
//param[3] - SBR
//param[4] - STPS

string HEAT = param[0];
string LUMB = param[1];
string VENT = param[2];
string SBR_ = param[3];
string STPS = param[4];

string output = "D46247AA";
// Byte-4 (Heat, Lumbar)
     if (HEAT=="0" && LUMB=="0") output = output + "00";
else if (HEAT=="0" && LUMB=="1") output = output + "01";
else if (HEAT=="1" && LUMB=="0") output = output + "04";
else if (HEAT=="1" && LUMB=="1") output = output + "05";
else if (HEAT=="0" && LUMB=="2") output = output + "02";
else if (HEAT=="1" && LUMB=="2") output = output + "06";

// Byte-5 (Massage, Mem, PwrBackRest, PwrCushExtn)
output = output + "14";
// Byte-6
     if (VENT=="0") output = output + "54";
else if (VENT=="1") output = output + "55";
// Byte-7, PassSeatRemCtrlFctAvl = 1
     if (SBR_=="0" && STPS=="0") output = output + "40";
else if (SBR_=="0" && STPS=="1") output = output + "44";
else if (SBR_=="1" && STPS=="0") output = output + "50";
else if (SBR_=="1" && STPS=="1") output = output + "54";

return output;

//compose CarConfigSET -- to be ECUCommand
//param[0] - HEAT
//param[1] - 2way-4way Lumbar, Not CFGed
//param[2] - Ventilation
//param[3] - SBR
//param[4] - STPS

string HEAT = param[0];
string LUMB = param[1];
string VENT = param[2];
string SBR_ = param[3];
string STPS = param[4];

string output = "542E47AA";
// Byte-4 (Heat, Lumbar)
     if (HEAT=="0" && LUMB=="0") output = output + "00";
else if (HEAT=="0" && LUMB=="1") output = output + "01";
else if (HEAT=="1" && LUMB=="0") output = output + "04";
else if (HEAT=="1" && LUMB=="1") output = output + "05";
else if (HEAT=="0" && LUMB=="2") output = output + "02";
else if (HEAT=="1" && LUMB=="2") output = output + "06";

// Byte-5 (Massage, Mem, PwrBackRest, PwrCushExtn)
output = output + "14";
// Byte-6
     if (VENT=="0") output = output + "54";
else if (VENT=="1") output = output + "55";
// Byte-7, PassSeatRemCtrlFctAvl = 1
     if (SBR_=="0" && STPS=="0") output = output + "40";
else if (SBR_=="0" && STPS=="1") output = output + "44";
else if (SBR_=="1" && STPS=="0") output = output + "50";
else if (SBR_=="1" && STPS=="1") output = output + "54";

return output;

float input1 = float.Parse(param[0]);
float input2 = float.Parse(param[1]);
string operation = param[2];

float result = 0;

if (operation=="ADD") result = input1 + input2;
if (operation=="SUB") result = input1 - input2;




return result;
